// src/pages/user-profile-settings/components/InterfaceCustomization.jsx
import React, { useState } from 'react';
import Icon from 'components/AppIcon';

const InterfaceCustomization = ({ settings, onSettingChange, themeColors }) => {
  const [localSettings, setLocalSettings] = useState({
    artisticEvolution: settings?.artisticEvolution || 'moderate',
    ephemeralElements: settings?.ephemeralElements || 'medium',
    gamificationIntensity: settings?.gamificationIntensity || 'standard',
    colorScheme: settings?.colorScheme || 'adaptive',
    animationLevel: settings?.animationLevel || 'full',
    compactMode: settings?.compactMode || false
  });

  const [previewMode, setPreviewMode] = useState(false);

  const handleChange = (key, value) => {
    const updated = { ...localSettings, [key]: value };
    setLocalSettings(updated);
    onSettingChange?.(updated);
  };

  const colorSchemes = [
    { id: 'adaptive', name: 'Adaptive', description: 'Changes based on time and mood', colors: ['#4F46E5', '#06B6D4', '#F59E0B'] },
    { id: 'ocean', name: 'Ocean', description: 'Calming blues and teals', colors: ['#0EA5E9', '#06B6D4', '#0891B2'] },
    { id: 'forest', name: 'Forest', description: 'Natural greens and browns', colors: ['#10B981', '#059669', '#065F46'] },
    { id: 'sunset', name: 'Sunset', description: 'Warm oranges and purples', colors: ['#F59E0B', '#EF4444', '#8B5CF6'] },
    { id: 'minimal', name: 'Minimal', description: 'Clean grays and whites', colors: ['#6B7280', '#374151', '#1F2937'] }
  ];

  const SliderSetting = ({ label, value, onChange, min = 0, max = 100, step = 1, description }) => (
    <div className="space-y-3">
      <div className="flex justify-between items-center">
        <label className="text-sm font-medium text-text-primary">{label}</label>
        <span className="text-xs text-text-secondary">{value}%</span>
      </div>
      <input
        type="range"
        min={min}
        max={max}
        step={step}
        value={value}
        onChange={(e) => onChange(parseInt(e.target.value))}
        className="w-full h-2 bg-border rounded-lg appearance-none cursor-pointer slider-thumb"
        style={{
          background: `linear-gradient(to right, ${themeColors?.primary || '#4F46E5'} 0%, ${themeColors?.primary || '#4F46E5'} ${value}%, #E5E7EB ${value}%, #E5E7EB 100%)`
        }}
      />
      {description && <p className="text-xs text-text-secondary">{description}</p>}
    </div>
  );

  return (
    <div className="space-y-6">
      {/* Preview Toggle */}
      <div className="flex items-center justify-between p-4 bg-surface-50 rounded-lg">
        <div>
          <h4 className="font-medium text-text-primary">Live Preview</h4>
          <p className="text-sm text-text-secondary">See changes in real-time</p>
        </div>
        <button
          onClick={() => setPreviewMode(!previewMode)}
          className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors duration-200 ${
            previewMode ? 'bg-primary' : 'bg-border'
          }`}
        >
          <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform duration-200 ${
            previewMode ? 'translate-x-6' : 'translate-x-1'
          }`} />
        </button>
      </div>

      {/* Color Scheme */}
      <div>
        <label className="block text-sm font-medium text-text-primary mb-3">
          Color Scheme
        </label>
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          {colorSchemes.map((scheme) => (
            <div
              key={scheme.id}
              onClick={() => handleChange('colorScheme', scheme.id)}
              className={`p-4 border rounded-lg cursor-pointer transition-all duration-200 hover:shadow-warm-sm ${
                localSettings.colorScheme === scheme.id
                  ? 'border-primary bg-primary-50' :'border-border hover:border-border-dark'
              }`}
            >
              <div className="flex items-center space-x-3 mb-2">
                <div className="flex space-x-1">
                  {scheme.colors.map((color, index) => (
                    <div
                      key={index}
                      className="w-4 h-4 rounded-full"
                      style={{ backgroundColor: color }}
                    />
                  ))}
                </div>
                <span className="font-medium text-text-primary">{scheme.name}</span>
              </div>
              <p className="text-xs text-text-secondary">{scheme.description}</p>
            </div>
          ))}
        </div>
      </div>

      {/* Artistic Evolution */}
      <div>
        <label className="block text-sm font-medium text-text-primary mb-3">
          Artistic Evolution Intensity
        </label>
        <SliderSetting
          label="Visual Adaptation Level"
          value={localSettings.artisticEvolution === 'subtle' ? 25 : localSettings.artisticEvolution === 'moderate' ? 50 : localSettings.artisticEvolution === 'dynamic' ? 75 : 100}
          onChange={(value) => {
            const level = value <= 25 ? 'subtle' : value <= 50 ? 'moderate' : value <= 75 ? 'dynamic' : 'immersive';
            handleChange('artisticEvolution', level);
          }}
          description="Controls how much the interface adapts to your learning patterns"
        />
      </div>

      {/* Ephemeral Elements */}
      <div>
        <label className="block text-sm font-medium text-text-primary mb-3">
          Ephemeral Design Elements
        </label>
        <SliderSetting
          label="Frequency of Dynamic Elements"
          value={localSettings.ephemeralElements === 'minimal' ? 20 : localSettings.ephemeralElements === 'medium' ? 50 : localSettings.ephemeralElements === 'frequent' ? 80 : 100}
          onChange={(value) => {
            const level = value <= 30 ? 'minimal' : value <= 60 ? 'medium' : value <= 85 ? 'frequent' : 'constant';
            handleChange('ephemeralElements', level);
          }}
          description="Temporary visual elements that appear during interactions"
        />
      </div>

      {/* Gamification */}
      <div>
        <label className="block text-sm font-medium text-text-primary mb-3">
          Gamification Intensity
        </label>
        <div className="space-y-2">
          {[
            { id: 'minimal', name: 'Minimal', description: 'Basic progress indicators only' },
            { id: 'standard', name: 'Standard', description: 'Points, badges, and streaks' },
            { id: 'enhanced', name: 'Enhanced', description: 'Leaderboards and competitions' },
            { id: 'immersive', name: 'Immersive', description: 'Full RPG-style progression system' }
          ].map((option) => (
            <label key={option.id} className="flex items-center space-x-3 p-3 border border-border rounded-lg hover:bg-surface-50 cursor-pointer transition-colors duration-200">
              <input
                type="radio"
                name="gamification"
                value={option.id}
                checked={localSettings.gamificationIntensity === option.id}
                onChange={(e) => handleChange('gamificationIntensity', e.target.value)}
                className="w-4 h-4 text-primary focus:ring-primary border-border"
              />
              <div>
                <div className="font-medium text-text-primary">{option.name}</div>
                <div className="text-xs text-text-secondary">{option.description}</div>
              </div>
            </label>
          ))}
        </div>
      </div>

      {/* Animation Level */}
      <div>
        <label className="block text-sm font-medium text-text-primary mb-3">
          Animation Level
        </label>
        <SliderSetting
          label="Interface Animations"
          value={localSettings.animationLevel === 'none' ? 0 : localSettings.animationLevel === 'reduced' ? 33 : localSettings.animationLevel === 'standard' ? 66 : 100}
          onChange={(value) => {
            const level = value === 0 ? 'none' : value <= 40 ? 'reduced' : value <= 75 ? 'standard' : 'full';
            handleChange('animationLevel', level);
          }}
          description="Controls transition and hover animations"
        />
      </div>

      {/* Compact Mode */}
      <div>
        <label className="flex items-center justify-between p-4 border border-border rounded-lg hover:bg-surface-50 cursor-pointer transition-colors duration-200">
          <div>
            <div className="font-medium text-text-primary">Compact Mode</div>
            <div className="text-sm text-text-secondary">Reduce spacing and element sizes</div>
          </div>
          <input
            type="checkbox"
            checked={localSettings.compactMode}
            onChange={(e) => handleChange('compactMode', e.target.checked)}
            className="w-4 h-4 text-primary focus:ring-primary border-border rounded"
          />
        </label>
      </div>

      {/* Preview Panel */}
      {previewMode && (
        <div className="p-4 border-2 border-dashed border-primary rounded-lg">
          <div className="flex items-center space-x-2 mb-3">
            <Icon name="Eye" size={16} className="text-primary" />
            <span className="text-sm font-medium text-primary">Live Preview</span>
          </div>
          <div 
            className="p-4 rounded-lg transition-all duration-300"
            style={{ 
              background: `linear-gradient(135deg, ${colorSchemes.find(s => s.id === localSettings.colorScheme)?.colors[0] || '#4F46E5'}15, ${colorSchemes.find(s => s.id === localSettings.colorScheme)?.colors[1] || '#06B6D4'}15)`
            }}
          >
            <div className="text-sm text-text-primary mb-2">Sample Learning Card</div>
            <div className="w-full bg-border rounded-full h-2 mb-2">
              <div 
                className="h-2 rounded-full transition-all duration-500"
                style={{ 
                  width: '60%',
                  backgroundColor: colorSchemes.find(s => s.id === localSettings.colorScheme)?.colors[0] || '#4F46E5'
                }}
              />
            </div>
            <div className="text-xs text-text-secondary">Progress: 60% complete</div>
          </div>
        </div>
      )}
    </div>
  );
};

export default InterfaceCustomization;