// src/pages/user-profile-settings/components/AccessibilitySettings.jsx
import React, { useState } from 'react';
import Icon from 'components/AppIcon';

const AccessibilitySettings = ({ settings, onSettingChange, themeColors }) => {
  const [localSettings, setLocalSettings] = useState({
    fontSize: settings?.fontSize || 'medium',
    highContrast: settings?.highContrast || false,
    reducedMotion: settings?.reducedMotion || false,
    screenReader: settings?.screenReader || false,
    keyboardNavigation: settings?.keyboardNavigation || false,
    colorBlindSupport: settings?.colorBlindSupport || 'none',
    audioDescriptions: settings?.audioDescriptions || false,
    autoDetection: settings?.autoDetection || true,
    focusIndicators: settings?.focusIndicators || true,
    customShortcuts: settings?.customShortcuts || []
  });

  const [showAutoDetected, setShowAutoDetected] = useState(false);

  const handleChange = (key, value) => {
    const updated = { ...localSettings, [key]: value };
    setLocalSettings(updated);
    onSettingChange?.(updated);
  };

  const accessibilityCategories = [
    {
      title: 'Visual Adaptations',
      icon: 'Eye',
      settings: [
        {
          id: 'fontSize',
          title: 'Text Size',
          type: 'select',
          options: [
            { value: 'small', label: 'Small (14px)' },
            { value: 'medium', label: 'Medium (16px)' },
            { value: 'large', label: 'Large (18px)' },
            { value: 'extra-large', label: 'Extra Large (20px)' }
          ],
          description: 'Adjust text size for better readability'
        },
        {
          id: 'highContrast',
          title: 'High Contrast Mode',
          type: 'toggle',
          description: 'Increase color contrast for better visibility'
        },
        {
          id: 'colorBlindSupport',
          title: 'Color Blind Support',
          type: 'select',
          options: [
            { value: 'none', label: 'None' },
            { value: 'deuteranopia', label: 'Deuteranopia (Red-Green)' },
            { value: 'protanopia', label: 'Protanopia (Red-Green)' },
            { value: 'tritanopia', label: 'Tritanopia (Blue-Yellow)' }
          ],
          description: 'Adjust colors for color vision differences'
        },
        {
          id: 'focusIndicators',
          title: 'Enhanced Focus Indicators',
          type: 'toggle',
          description: 'Show clear visual indicators for focused elements'
        }
      ]
    },
    {
      title: 'Auditory Adaptations',
      icon: 'Volume2',
      settings: [
        {
          id: 'screenReader',
          title: 'Screen Reader Optimization',
          type: 'toggle',
          description: 'Optimize interface for screen readers and assistive technologies'
        },
        {
          id: 'audioDescriptions',
          title: 'Audio Descriptions',
          type: 'toggle',
          description: 'Enable audio descriptions for visual content'
        }
      ]
    },
    {
      title: 'Motor Adaptations',
      icon: 'Hand',
      settings: [
        {
          id: 'keyboardNavigation',
          title: 'Enhanced Keyboard Navigation',
          type: 'toggle',
          description: 'Enable full keyboard navigation with custom shortcuts'
        },
        {
          id: 'reducedMotion',
          title: 'Reduce Motion',
          type: 'toggle',
          description: 'Minimize animations and transitions that may cause discomfort'
        }
      ]
    }
  ];

  const autoDetectedFeatures = [
    { feature: 'High Contrast', detected: true, confidence: 95 },
    { feature: 'Large Text', detected: false, confidence: 30 },
    { feature: 'Screen Reader', detected: true, confidence: 85 },
    { feature: 'Reduced Motion', detected: false, confidence: 15 }
  ];

  const renderSetting = (setting) => {
    switch (setting.type) {
      case 'toggle':
        return (
          <div className="flex items-center justify-between">
            <div>
              <h4 className="font-medium text-text-primary">{setting.title}</h4>
              <p className="text-sm text-text-secondary">{setting.description}</p>
            </div>
            <button
              onClick={() => handleChange(setting.id, !localSettings[setting.id])}
              className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors duration-200 ${
                localSettings[setting.id] ? 'bg-primary' : 'bg-border'
              }`}
            >
              <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform duration-200 ${
                localSettings[setting.id] ? 'translate-x-6' : 'translate-x-1'
              }`} />
            </button>
          </div>
        );
      
      case 'select':
        return (
          <div>
            <label className="block font-medium text-text-primary mb-2">{setting.title}</label>
            <select
              value={localSettings[setting.id]}
              onChange={(e) => handleChange(setting.id, e.target.value)}
              className="w-full p-3 border border-border rounded-lg bg-surface focus:outline-none focus:ring-2 focus:ring-primary focus:border-transparent"
            >
              {setting.options.map((option) => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </select>
            <p className="text-sm text-text-secondary mt-1">{setting.description}</p>
          </div>
        );
      
      default:
        return null;
    }
  };

  return (
    <div className="space-y-6">
      {/* Auto-Detection Banner */}
      <div className="bg-primary-50 border border-primary-200 rounded-lg p-4">
        <div className="flex items-start space-x-3">
          <div className="w-8 h-8 bg-primary rounded-full flex items-center justify-center flex-shrink-0">
            <Icon name="Zap" size={16} color="white" />
          </div>
          <div className="flex-1">
            <div className="flex items-center justify-between mb-2">
              <h4 className="font-semibold text-text-primary">Automatic Detection</h4>
              <button
                onClick={() => setShowAutoDetected(!showAutoDetected)}
                className="text-sm text-primary hover:text-primary-700 font-medium"
              >
                {showAutoDetected ? 'Hide Details' : 'Show Details'}
              </button>
            </div>
            <p className="text-sm text-text-secondary mb-3">
              We automatically detect accessibility preferences from your system settings.
            </p>
            
            {showAutoDetected && (
              <div className="space-y-2 mt-3">
                {autoDetectedFeatures.map((item, index) => (
                  <div key={index} className="flex items-center justify-between p-2 bg-white rounded border">
                    <span className="text-sm font-medium">{item.feature}</span>
                    <div className="flex items-center space-x-2">
                      <span className={`text-xs px-2 py-1 rounded-full ${
                        item.detected ? 'bg-success-100 text-success-700' : 'bg-surface-100 text-text-secondary'
                      }`}>
                        {item.confidence}% confidence
                      </span>
                      <Icon 
                        name={item.detected ? 'Check' : 'X'} 
                        size={16} 
                        className={item.detected ? 'text-success-600' : 'text-text-secondary'}
                      />
                    </div>
                  </div>
                ))}
              </div>
            )}
            
            <div className="flex items-center space-x-3 mt-3">
              <label className="flex items-center space-x-2">
                <input
                  type="checkbox"
                  checked={localSettings.autoDetection}
                  onChange={(e) => handleChange('autoDetection', e.target.checked)}
                  className="w-4 h-4 text-primary focus:ring-primary border-border rounded"
                />
                <span className="text-sm text-text-primary">Enable automatic detection</span>
              </label>
            </div>
          </div>
        </div>
      </div>

      {/* Accessibility Categories */}
      {accessibilityCategories.map((category) => (
        <div key={category.title} className="border border-border rounded-lg overflow-hidden">
          <div className="bg-surface-50 px-6 py-4 border-b border-border">
            <div className="flex items-center space-x-3">
              <div 
                className="w-10 h-10 rounded-lg flex items-center justify-center"
                style={{ backgroundColor: `${themeColors?.primary || '#4F46E5'}15` }}
              >
                <Icon 
                  name={category.icon} 
                  size={20} 
                  style={{ color: themeColors?.primary || '#4F46E5' }}
                />
              </div>
              <h3 className="text-lg font-heading font-semibold text-text-primary">
                {category.title}
              </h3>
            </div>
          </div>
          <div className="p-6 space-y-6">
            {category.settings.map((setting) => (
              <div key={setting.id}>
                {renderSetting(setting)}
              </div>
            ))}
          </div>
        </div>
      ))}

      {/* Custom Shortcuts */}
      <div className="border border-border rounded-lg p-6">
        <h3 className="text-lg font-heading font-semibold text-text-primary mb-4">
          Custom Keyboard Shortcuts
        </h3>
        <div className="space-y-3">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {[
              { action: 'Start Learning Session', shortcut: 'Ctrl + L', customizable: true },
              { action: 'Open Notes', shortcut: 'Ctrl + N', customizable: true },
              { action: 'Toggle Focus Mode', shortcut: 'Ctrl + F', customizable: true },
              { action: 'Skip to Next Topic', shortcut: 'Ctrl + →', customizable: true }
            ].map((item, index) => (
              <div key={index} className="flex items-center justify-between p-3 border border-border rounded-lg">
                <span className="text-sm font-medium text-text-primary">{item.action}</span>
                <div className="flex items-center space-x-2">
                  <kbd className="px-2 py-1 bg-surface-100 border border-border rounded text-xs font-mono">
                    {item.shortcut}
                  </kbd>
                  {item.customizable && (
                    <button className="text-xs text-primary hover:text-primary-700">
                      Edit
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Test Accessibility */}
      <div className="bg-accent-50 border border-accent-200 rounded-lg p-4">
        <div className="flex items-start space-x-3">
          <Icon name="TestTube" size={20} className="text-accent-600 flex-shrink-0 mt-0.5" />
          <div>
            <h4 className="font-medium text-accent-800 mb-1">Test Your Settings</h4>
            <p className="text-sm text-accent-700 mb-3">
              Try our accessibility testing tool to ensure your settings work well for your needs.
            </p>
            <button className="px-4 py-2 bg-accent-600 text-white rounded-lg hover:bg-accent-700 transition-colors duration-200 text-sm font-medium">
              Run Accessibility Test
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AccessibilitySettings;