// src/pages/user-profile-settings/components/SettingsAccordion.jsx
import React, { useState } from 'react';
import Icon from 'components/AppIcon';

const SettingsAccordion = ({ title, icon, children, defaultOpen = false, themeColors }) => {
  const [isOpen, setIsOpen] = useState(defaultOpen);

  return (
    <div className="bg-surface border border-border rounded-xl mb-4 overflow-hidden shadow-warm-sm transition-all duration-300 hover:shadow-warm-md">
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="w-full px-6 py-4 flex items-center justify-between hover:bg-surface-50 transition-colors duration-200"
      >
        <div className="flex items-center space-x-3">
          <div 
            className="w-10 h-10 rounded-lg flex items-center justify-center"
            style={{ backgroundColor: `${themeColors?.primary || '#4F46E5'}15` }}
          >
            <Icon 
              name={icon} 
              size={20} 
              style={{ color: themeColors?.primary || '#4F46E5' }}
            />
          </div>
          <h3 className="text-lg font-heading font-semibold text-text-primary">
            {title}
          </h3>
        </div>
        <Icon 
          name="ChevronDown" 
          size={20} 
          className={`text-text-secondary transition-transform duration-200 ${
            isOpen ? 'rotate-180' : ''
          }`} 
        />
      </button>
      
      <div className={`transition-all duration-300 ease-in-out ${
        isOpen ? 'max-h-screen opacity-100' : 'max-h-0 opacity-0'
      } overflow-hidden`}>
        <div className="px-6 pb-6 border-t border-border-light">
          <div className="pt-4">
            {children}
          </div>
        </div>
      </div>
    </div>
  );
};

export default SettingsAccordion;