// src/pages/user-profile-settings/components/UserProfileHeader.jsx
import React, { useState } from 'react';
import Icon from 'components/AppIcon';

const UserProfileHeader = ({ userProfile, onAvatarChange, themeColors }) => {
  const [isHovering, setIsHovering] = useState(false);

  const handleAvatarClick = () => {
    // Simulate file input click
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.onchange = (e) => {
      const file = e.target.files?.[0];
      if (file) {
        const reader = new FileReader();
        reader.onload = (event) => {
          onAvatarChange?.(event.target.result);
        };
        reader.readAsDataURL(file);
      }
    };
    input.click();
  };

  return (
    <div className="bg-surface border border-border rounded-xl p-6 mb-6 shadow-warm-sm">
      <div className="flex flex-col sm:flex-row items-center space-y-4 sm:space-y-0 sm:space-x-6">
        {/* Avatar */}
        <div 
          className="relative cursor-pointer group"
          onClick={handleAvatarClick}
          onMouseEnter={() => setIsHovering(true)}
          onMouseLeave={() => setIsHovering(false)}
        >
          <div 
            className="w-24 h-24 rounded-full flex items-center justify-center transition-all duration-300 group-hover:scale-105"
            style={{ 
              background: userProfile?.avatar 
                ? `url(${userProfile.avatar}) center/cover`
                : `linear-gradient(135deg, ${themeColors?.primary || '#4F46E5'}, ${themeColors?.secondary || '#06B6D4'})`
            }}
          >
            {!userProfile?.avatar && (
              <Icon name="User" size={32} color="white" />
            )}
          </div>
          <div className="absolute inset-0 bg-black bg-opacity-50 rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-300">
            <Icon name="Camera" size={20} color="white" />
          </div>
        </div>

        {/* User Info */}
        <div className="flex-1 text-center sm:text-left">
          <h2 className="text-2xl font-heading font-bold text-text-primary mb-2">
            {userProfile?.name || 'Alex Johnson'}
          </h2>
          <p className="text-text-secondary font-body mb-1">
            {userProfile?.email || 'alex.johnson@email.com'}
          </p>
          <div className="flex flex-wrap justify-center sm:justify-start gap-2 mt-3">
            <span 
              className="px-3 py-1 rounded-full text-xs font-medium text-white"
              style={{ backgroundColor: themeColors?.primary || '#4F46E5' }}
            >
              Learning Level: {userProfile?.learningLevel || 'Intermediate'}
            </span>
            <span 
              className="px-3 py-1 rounded-full text-xs font-medium text-white"
              style={{ backgroundColor: themeColors?.accent || '#F59E0B' }}
            >
              Streak: {userProfile?.streak || 7} days
            </span>
          </div>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-3 gap-4 text-center">
          <div>
            <p className="text-lg font-bold text-text-primary">
              {userProfile?.completedCourses || 12}
            </p>
            <p className="text-xs text-text-secondary font-caption">Completed</p>
          </div>
          <div>
            <p className="text-lg font-bold text-text-primary">
              {Number(userProfile?.totalHours || 156).toFixed(1)}
            </p>
            <p className="text-xs text-text-secondary font-caption">Hours</p>
          </div>
          <div>
            <p className="text-lg font-bold text-text-primary">
              {userProfile?.achievements || 23}
            </p>
            <p className="text-xs text-text-secondary font-caption">Badges</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default UserProfileHeader;