// src/pages/user-profile-settings/components/LearningPreferences.jsx
import React, { useState } from 'react';
import Icon from 'components/AppIcon';

const LearningPreferences = ({ preferences, onPreferenceChange, themeColors }) => {
  const [localPreferences, setLocalPreferences] = useState({
    learningStyle: preferences?.learningStyle || 'visual',
    difficultyPreference: preferences?.difficultyPreference || 'adaptive',
    pacePreference: preferences?.pacePreference || 'moderate',
    subjectInterests: preferences?.subjectInterests || ['mathematics', 'programming'],
    accessibilityNeeds: preferences?.accessibilityNeeds || []
  });

  const handleChange = (key, value) => {
    const updated = { ...localPreferences, [key]: value };
    setLocalPreferences(updated);
    onPreferenceChange?.(updated);
  };

  const learningStyles = [
    { id: 'visual', name: 'Visual', icon: 'Eye', description: 'Learn through images, diagrams, and visual content' },
    { id: 'auditory', name: 'Auditory', icon: 'Volume2', description: 'Learn through listening and verbal instruction' },
    { id: 'kinesthetic', name: 'Kinesthetic', icon: 'Hand', description: 'Learn through hands-on activities and movement' },
    { id: 'reading', name: 'Reading/Writing', icon: 'BookOpen', description: 'Learn through reading and writing activities' },
    { id: 'analytical', name: 'Analytical & Logical', icon: 'Calculator', description: 'Learn through structured flow, step-by-step reasoning, and coding quizzes' },
    { id: 'socratic', name: 'Socratic & Inquiry-based', icon: 'MessageCircle', description: 'Learn through inquiry, dialogue, and guided questioning' }
  ];

  const subjectOptions = [
    { id: 'mathematics', name: 'Mathematics', icon: 'Calculator' },
    { id: 'programming', name: 'Programming', icon: 'Code' },
    { id: 'history', name: 'History', icon: 'Clock' },
    { id: 'science', name: 'Science', icon: 'Microscope' },
    { id: 'languages', name: 'Languages', icon: 'MessageCircle' },
    { id: 'arts', name: 'Arts', icon: 'Palette' }
  ];

  const accessibilityOptions = [
    { id: 'large-text', name: 'Large Text', icon: 'Type' },
    { id: 'high-contrast', name: 'High Contrast', icon: 'Contrast' },
    { id: 'screen-reader', name: 'Screen Reader Support', icon: 'Volume2' },
    { id: 'reduced-motion', name: 'Reduced Motion', icon: 'Pause' },
    { id: 'keyboard-navigation', name: 'Keyboard Navigation', icon: 'Keyboard' }
  ];

  const toggleSubjectInterest = (subjectId) => {
    const current = localPreferences.subjectInterests;
    const updated = current.includes(subjectId)
      ? current.filter(id => id !== subjectId)
      : [...current, subjectId];
    handleChange('subjectInterests', updated);
  };

  const toggleAccessibilityNeed = (needId) => {
    const current = localPreferences.accessibilityNeeds;
    const updated = current.includes(needId)
      ? current.filter(id => id !== needId)
      : [...current, needId];
    handleChange('accessibilityNeeds', updated);
  };

  return (
    <div className="space-y-6">
      {/* AI Recommendation Banner */}
      <div className="bg-gradient-to-r from-primary-50 to-secondary-50 border border-primary-100 rounded-lg p-4">
        <div className="flex items-start space-x-3">
          <div className="w-8 h-8 bg-primary rounded-full flex items-center justify-center flex-shrink-0">
            <Icon name="Zap" size={16} color="white" />
          </div>
          <div>
            <h4 className="font-semibold text-text-primary mb-1">AI Recommendations</h4>
            <p className="text-sm text-text-secondary">
              Based on your learning behavior, we've detected you prefer visual learning with moderate difficulty progression.
            </p>
          </div>
        </div>
      </div>

      {/* Learning Style */}
      <div>
        <label className="block text-sm font-medium text-text-primary mb-3">
          Preferred Learning Style
        </label>
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          {learningStyles.map((style) => (
            <div
              key={style.id}
              onClick={() => handleChange('learningStyle', style.id)}
              className={`p-4 border rounded-lg cursor-pointer transition-all duration-200 hover:shadow-warm-sm ${
                localPreferences.learningStyle === style.id
                  ? 'border-primary bg-primary-50' :'border-border hover:border-border-dark'
              }`}
            >
              <div className="flex items-center space-x-3 mb-2">
                <Icon name={style.icon} size={20} className="text-primary" />
                <span className="font-medium text-text-primary">{style.name}</span>
              </div>
              <p className="text-xs text-text-secondary">{style.description}</p>
            </div>
          ))}
        </div>
      </div>

      {/* Difficulty Preference */}
      <div>
        <label className="block text-sm font-medium text-text-primary mb-3">
          Difficulty Preference
        </label>
        <div className="space-y-2">
          {[
            { id: 'easy', name: 'Easy', description: 'Gentle progression with lots of practice' },
            { id: 'moderate', name: 'Moderate', description: 'Balanced challenge and support' },
            { id: 'challenging', name: 'Challenging', description: 'Fast-paced with advanced concepts' },
            { id: 'adaptive', name: 'Adaptive (Recommended)', description: 'AI adjusts difficulty based on performance' }
          ].map((option) => (
            <label key={option.id} className="flex items-center space-x-3 p-3 border border-border rounded-lg hover:bg-surface-50 cursor-pointer transition-colors duration-200">
              <input
                type="radio"
                name="difficulty"
                value={option.id}
                checked={localPreferences.difficultyPreference === option.id}
                onChange={(e) => handleChange('difficultyPreference', e.target.value)}
                className="w-4 h-4 text-primary focus:ring-primary border-border"
              />
              <div>
                <div className="font-medium text-text-primary">{option.name}</div>
                <div className="text-xs text-text-secondary">{option.description}</div>
              </div>
            </label>
          ))}
        </div>
      </div>

      {/* Subject Interests */}
      <div>
        <label className="block text-sm font-medium text-text-primary mb-3">
          Subject Interests
        </label>
        <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
          {subjectOptions.map((subject) => (
            <div
              key={subject.id}
              onClick={() => toggleSubjectInterest(subject.id)}
              className={`p-3 border rounded-lg cursor-pointer transition-all duration-200 hover:shadow-warm-sm text-center ${
                localPreferences.subjectInterests.includes(subject.id)
                  ? 'border-primary bg-primary-50' :'border-border hover:border-border-dark'
              }`}
            >
              <Icon name={subject.icon} size={24} className="text-primary mx-auto mb-2" />
              <span className="text-sm font-medium text-text-primary">{subject.name}</span>
            </div>
          ))}
        </div>
      </div>

      {/* Accessibility Needs */}
      <div>
        <label className="block text-sm font-medium text-text-primary mb-3">
          Accessibility Needs
        </label>
        <div className="space-y-2">
          {accessibilityOptions.map((option) => (
            <label key={option.id} className="flex items-center space-x-3 p-3 border border-border rounded-lg hover:bg-surface-50 cursor-pointer transition-colors duration-200">
              <input
                type="checkbox"
                checked={localPreferences.accessibilityNeeds.includes(option.id)}
                onChange={() => toggleAccessibilityNeed(option.id)}
                className="w-4 h-4 text-primary focus:ring-primary border-border rounded"
              />
              <Icon name={option.icon} size={20} className="text-text-secondary" />
              <span className="font-medium text-text-primary">{option.name}</span>
            </label>
          ))}
        </div>
      </div>
    </div>
  );
};

export default LearningPreferences;